for cls, names in _EQUAL_FIELDS:
            if kind is cls:
                ledger.charge("traversal", len(names), stage=stage)
                for name in names:
                    _same(
                        getattr(left, name),
                        getattr(right, name),
                        ledger,
                        domain=domain,
                        stage=stage,
                    )
                return

{
            name: self.integer(value[name], minimum=0, maximum=maximum) for name, maximum in _LIMITS
        }

{
            name: self.integer(value[name], minimum=0, maximum=getattr(limits, name))
            for name in _COUNTERS
        }

{
            name: self.integer(value["limits"][name], minimum=maximum, maximum=maximum)
            for name, maximum in maxima
        }

for name, maximum in _LIMITS:
            if name not in ("work", "output_bytes"):
                _require(entry[name] == maximum)

while position:
                compared = self.id_compare(name, ordered[position - 1][1])
                _require(compared != 0, "A3")
                if compared > 0:
                    break
                position -= 1

for field, default in _LIMITS:
                actual = getattr(child.limits, field)
                _require(type(actual) is int, "A3")
                total_pool = semantic._PROFILE_POOLS.get(field)
                expected = (
                    default
                    if total_pool is None
                    else (total_pool // len(ordered) + (slot < total_pool % len(ordered)))
                )
                _require(actual == expected, "A3")

for slot, (_, candidate) in enumerate(ordered):
            if candidate is not None and self.id_compare(name, candidate) == 0:
                return slot

(
            self.child(raw, i, ordered, flags, definitions, catalog)
            for i, raw in enumerate(children)
        )

for child in native_children:
            batch = child["batch"]
            if batch is not None:
                for firing in batch.firings:
                    _same(native_groups[cursor], firing, self.ledger, stage="A5")
                    cursor += 1

for firing in batch.firings:
                    _same(native_groups[cursor], firing, self.ledger, stage="A5")
                    cursor += 1

for pair, key in zip(e.implementation, _IDENTITY, strict=True):
        _require(
            type(pair) is tuple and len(pair) == 2 and type(pair[0]) is str and pair[0] == key,
            "entry",
        )
        decoder.string(pair[1], 16384)

for key, value in (
        ("inputDigest", expected.input_digest),
        ("sourceDigest", expected.source_digest),
        ("definitionsDigest", expected.definitions_digest),
    ):
        _same(decoder.sha(raw[key]), value, ledger, stage="A3")

(
            tuple(occurrences[i + j]["value"] for j in range(3))
            for i in range(0, len(occurrences), 3)
        )

for pair in overrides:
            if (
                type(pair) is not tuple
                or len(pair) != 2
                or type(pair[0]) is not str
                or pair[0] not in _DOMAINS
                or not _integer(pair[1])
            ):
                reject()
            if any(pair[0] == name for name, _ in checked):
                reject()
            checked.append(pair)

for name, limit in self._overrides:
            if limit > caps[name]:
                reject("RESTORE_EXPECTATION_MISMATCH", "expectation", domain=name)
            caps[name] = limit

while self.pos < self.length:
            c = self.text[self.pos]
            if c == '"':
                end = self.pos
                self.pos += 1
                if (
                    maximum is not None and decoded_bytes > maximum
                ) or decoded_chars > character_limit:
                    reject("RESTORE_LIMIT", "resource", stage="A1", domain="copy")
                if not self.build and not key:
                    return None
                if self.build and not key:
                    # scanstring may allocate now, after the token-length and
                    # Unicode gates completed. UTF8 escape output <= token bytes.
                    self.ledger.charge("copy", end - start, stage="A1")
                    self.ledger.reserve("scalar", 4 * (end - start), stage="A1")
                try:
                    value, stop = scanstring(self.text, start, True)
                except (ValueError, OverflowError):
                    self.bad()
                if stop != self.pos:
                    self.bad()
                return value
            if ord(c) < 32:
                self.bad()
            if c == "\\":
                self.pos += 1
                if self.pos >= self.length:
                    self.bad()
                escape = self.text[self.pos]
                if escape in '"\\/bfnrt':
                    decoded_bytes += 1
                    decoded_chars += 1
                    self.pos += 1
                    continue
                if escape != "u":
                    self.bad()
                code = self.hex4(self.pos + 1)
                self.pos += 5
                if 0xD800 <= code <= 0xDBFF:
                    if self.text[self.pos : self.pos + 2] != "\\u":
                        self.bad()
                    low = self.hex4(self.pos + 2)
                    if not 0xDC00 <= low <= 0xDFFF:
                        self.bad()
                    self.pos += 6
                    code = 0x10000 + ((code - 0xD800) << 10) + low - 0xDC00
                elif 0xDC00 <= code <= 0xDFFF:
                    self.bad()
                decoded_bytes += _width(code)
            else:
                code = ord(c)
                if 0xD800 <= code <= 0xDFFF:
                    self.bad()
                decoded_bytes += _width(code)
                self.pos += 1
            decoded_chars += 1
            if (maximum is not None and decoded_bytes > maximum) or decoded_chars > character_limit:
                reject("RESTORE_LIMIT", "resource", stage="A1", domain="copy")

for i in range(start, start + 4):
            c = self.text[i]
            if "0" <= c <= "9":
                digit = ord(c) - 48
            elif "a" <= c <= "f":
                digit = ord(c) - 87
            elif "A" <= c <= "F":
                digit = ord(c) - 55
            else:
                self.bad()
            value = value * 16 + digit

for known in JSON_KEYS:
            self.ledger.charge("schema", len(value) + len(known) + 1, stage="A1")
            if value == known:
                return known

for token, result in (("null", None), ("true", True), ("false", False)):
            if self.text.startswith(token, self.pos):
                self.pos += len(token)
                return result

while True:
            self.space()
            if self.pos >= self.length or self.text[self.pos] != '"' or len(keys) >= 32:
                self.bad()
            self.node(depth + 1)
            key = self.fixed_key(self.string(key=True))
            for prior in keys:
                self.ledger.charge("schema", len(key) + len(prior) + 1, stage="A1")
                if key == prior:
                    self.bad()
            keys.append(key)
            self.space()
            if self.pos >= self.length or self.text[self.pos] != ":":
                self.bad()
            self.pos += 1
            item = self.value(depth + 1, field=key)
            if self.build:
                self.ledger.visit(1, stage="A1")
                self.ledger.reserve("objects", 1, stage="A1")
                result[key] = item
            self.space()
            if self.pos >= self.length:
                self.bad()
            delimiter = self.text[self.pos]
            self.pos += 1
            if delimiter == "}":
                return result
            if delimiter != ",":
                self.bad()

for prior in keys:
                self.ledger.charge("schema", len(key) + len(prior) + 1, stage="A1")
                if key == prior:
                    self.bad()

while True:
            item = self.value(depth + 1)
            if self.build:
                self.ledger.visit(stage="A1")
                self.ledger.reserve("objects", 1, stage="A1")
                result.append(item)
            self.space()
            if self.pos >= self.length:
                self.bad()
            delimiter = self.text[self.pos]
            self.pos += 1
            if delimiter == "]":
                return result
            if delimiter != ",":
                self.bad()

for position in range(start, len(text)):
        if text[position] not in "0123456789abcdef":
            reject(stage=stage)

for position in range(start, len(text), 8):
            piece = text[position : position + 8]
            value = (value << (4 * len(piece))) | int(piece, 16)

for c in text:
        if c not in "0123456789abcdef":
            reject(stage=stage)

for c in text:
        code = ord(c)
        if 0xD800 <= code <= 0xDFFF:
            reject(stage="A4")
        size += _width(code)
        if size > maximum:
            reject("RESTORE_LIMIT", "resource", stage="A4", domain="copy")

for i, value in enumerate(fields):
            maximum = 16384 if i < 4 else 65536
            sizes.append(0 if value is None else _text_size(value, ledger, maximum))

for value, size in zip(fields, sizes, strict=True):
                sink.append(0 if value is None else 1)
                sink.extend(size.to_bytes(4, "big"))
                if value is not None:
                    sink.extend(value.encode("utf-8", errors="strict"))

for index, candidate in enumerate(node.children):
                ledger.charge("cache_query", 1, stage="A4")
                if candidate.key[candidate.start] == key[position]:
                    child_index, child = index, candidate
                    break
